import React, { useEffect, useMemo, useRef, useState } from 'react';
import { casesAPI, openingsAPI } from '../services/api';
import ImageWithFallback from './ImageWithFallback';
import './CaseOpeningAnimation.css';

const SLOT_WIDTH = 156;
const WINNER_INDEX = 42;
const TOTAL_SLOTS = 64;
const ANIMATION_MS = 6200;

const CaseOpeningAnimation = ({ caseId, onComplete, onClose }) => {
  const [caseData, setCaseData] = useState(null);
  const [openingResult, setOpeningResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [phase, setPhase] = useState('loading'); // loading | rolling | finished
  const [translateX, setTranslateX] = useState(0);
  const viewportRef = useRef(null);
  const completedRef = useRef(false);
  const onCompleteRef = useRef(onComplete);

  useEffect(() => { onCompleteRef.current = onComplete; }, [onComplete]);

  // IMPORTANT: this effect runs only once per caseId. Parent re-renders (for example
  // after updateBalance()) must never restart an already completed opening.
  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setError('');
      setPhase('loading');
      setOpeningResult(null);
      setTranslateX(0);
      completedRef.current = false;
      try {
        const [caseResponse, openingResponse] = await Promise.all([
          casesAPI.getCaseById(caseId),
          openingsAPI.openCase(caseId),
        ]);
        if (cancelled) return;
        setCaseData(caseResponse.data);
        setOpeningResult(openingResponse.data);
        setLoading(false);
        // Let the browser paint the ready state before beginning the roll.
        window.setTimeout(() => {
          if (!cancelled) setPhase('rolling');
        }, 180);
      } catch (err) {
        if (!cancelled) {
          setError(err.response?.data?.detail || 'Impossible d’ouvrir cette caisse.');
          setLoading(false);
        }
      }
    };
    if (caseId) load();
    return () => { cancelled = true; };
  }, [caseId]);

  const wonItem = openingResult?.item || null;
  const sequence = useMemo(() => {
    if (!caseData?.items?.length || !wonItem) return [];
    const pool = caseData.items;
    const alternatives = pool.filter((item) => item.id !== wonItem.id);
    return Array.from({ length: TOTAL_SLOTS }, (_, index) => {
      if (index === WINNER_INDEX) return wonItem;
      const source = alternatives.length ? alternatives : pool;
      return source[Math.floor(Math.random() * source.length)];
    });
  }, [caseData, wonItem]);

  useEffect(() => {
    if (phase !== 'rolling' || !sequence.length || !wonItem) return undefined;
    const viewportWidth = viewportRef.current?.clientWidth || 900;
    const winnerCenter = WINNER_INDEX * SLOT_WIDTH + SLOT_WIDTH / 2;
    const target = Math.round(viewportWidth / 2 - winnerCenter);
    setTranslateX(0);
    const frame = window.requestAnimationFrame(() => setTranslateX(target));
    const finishTimer = window.setTimeout(() => {
      setPhase('finished');
      if (!completedRef.current) {
        completedRef.current = true;
        onCompleteRef.current?.(wonItem);
      }
    }, ANIMATION_MS + 120);
    return () => {
      window.cancelAnimationFrame(frame);
      window.clearTimeout(finishTimer);
    };
  }, [phase, sequence, wonItem]);

  if (loading) {
    return <div className="opening-animation-container opening-state"><div className="opening-loader" /><span className="opening-kicker">WELLCASE DROP</span><strong>Préparation du drop…</strong></div>;
  }
  if (error || !caseData || !wonItem) {
    return <div className="opening-animation-container opening-state"><span className="opening-kicker">DROP ERROR</span><h4>Ouverture indisponible</h4><p>{error || 'Le résultat de l’ouverture est incomplet.'}</p><button className="opening-collect-button" onClick={onClose}>FERMER</button></div>;
  }

  const rarityClass = (rarity) => rarity ? `rarity-${rarity.toLowerCase().replace(/\s+/g, '-')}` : 'rarity-default';
  const isFinished = phase === 'finished';

  return (
    <div className={`opening-animation-container ${phase}`}>
      <div className="opening-backdrop-orb orb-a" /><div className="opening-backdrop-orb orb-b" />
      <div className="opening-header">
        <span className="opening-kicker">WELLCASE DROP</span>
        <h3>{caseData.name}</h3>
        <p>Une ouverture. Un résultat. Une animation premium.</p>
      </div>

      <div className="opening-viewport" ref={viewportRef}>
        <div className="opening-sheen" />
        <div className="opening-pointer" aria-hidden="true"><span /></div>
        <div className="opening-track" style={{ width: `${sequence.length * SLOT_WIDTH}px`, transform: `translate3d(${translateX}px,0,0)` }}>
          {sequence.map((item, index) => (
            <div className="opening-slide-item" key={`${item.id}-${index}`} style={{ width: SLOT_WIDTH }}>
              <div className="opening-item-card">
                <div className="opening-item-rarity-line" />
                <ImageWithFallback src={item.image_url} alt={item.name} className="opening-item-image" />
                <div className="item-name" title={item.name}>{item.name}</div>
                <div className={`item-rarity ${rarityClass(item.rarity)}`}>{item.rarity}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="opening-progress"><span /><span /><span /><span /><span /></div>
      <div className="opening-status">
        {!isFinished ? <><span className="status-label">OUVERTURE EN COURS</span><strong>La roulette révèle ton drop…</strong><small>Le résultat a été sécurisé par le serveur.</small></> : <><span className="status-label win">DROP CONFIRMÉ</span><strong>{wonItem.name}</strong><small>{Number(wonItem.virtual_value).toLocaleString('fr-FR')} € · {wonItem.rarity}</small></>}
      </div>

      {isFinished && (
        <div className="won-item-display">
          <div className="won-item-glow"><div className="won-item-rays" /><ImageWithFallback src={wonItem.image_url} alt={wonItem.name} className="won-item-image" /></div>
          <div className="won-item-name">{wonItem.name}</div>
          <div className={`won-item-rarity ${rarityClass(wonItem.rarity)}`}>{wonItem.rarity} · {Number(wonItem.virtual_value).toLocaleString('fr-FR')} €</div>
          <button className="opening-collect-button" onClick={onClose}>RÉCUPÉRER LE SKIN</button>
        </div>
      )}
    </div>
  );
};

export default CaseOpeningAnimation;
